import{_ as t,o as d,c as o,a2 as a}from"./chunks/framework.D9DTPhg1.js";const b=JSON.parse('{"title":"Attributes","description":"","frontmatter":{},"headers":[],"relativePath":"reference/attributes.md","filePath":"website/reference/attributes.md"}'),r={name:"reference/attributes.md"};function c(n,e,i,l,h,s){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="attributes" tabindex="-1">Attributes <a class="header-anchor" href="#attributes" aria-label="Permalink to &quot;Attributes&quot;">​</a></h1><p>Every attribute of Prism, with each of its parameters. The mapping attributes live in <code>Prism\\Orm\\Mapping</code> and are written with the <code>Prism\\</code> alias (<code>use Prism\\Orm\\Mapping as Prism;</code>); the others are named with their namespace.</p><p>This page is checked against the code: a parameter added to an attribute fails the build until it is documented here.</p><h2 id="entities" tabindex="-1">Entities <a class="header-anchor" href="#entities" aria-label="Permalink to &quot;Entities&quot;">​</a></h2><h3 id="entity" tabindex="-1"><code>#[Entity]</code> <a class="header-anchor" href="#entity" aria-label="Permalink to &quot;`#[Entity]`&quot;">​</a></h3><p>Makes a class an entity. Class attribute. See <a href="/prism/guide/mapping#entities-and-tables">Mapping entities</a>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>repositoryClass</code></td><td><code>null</code></td><td>The class returned by <code>getRepository()</code>; it extends <code>EntityRepository</code>. <code>null</code>: <code>EntityRepository</code></td></tr><tr><td><code>trackingPolicy</code></td><td><code>TrackingPolicy::Implicit</code></td><td><code>Implicit</code>: every managed entity is compared at flush. <code>Explicit</code>: only the entities passed to <code>persist()</code> since the last flush</td></tr><tr><td><code>readOnly</code></td><td><code>false</code></td><td>The entity is never compared at flush: it is inserted and deleted, never updated</td></tr></tbody></table><h3 id="table" tabindex="-1"><code>#[Table]</code> <a class="header-anchor" href="#table" aria-label="Permalink to &quot;`#[Table]`&quot;">​</a></h3><p>The table of the entity. Class attribute.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td><code>null</code></td><td>The table name. <code>null</code>: the class name in snake case (<code>OrderLine</code> → <code>order_line</code>)</td></tr><tr><td><code>options</code></td><td><code>[]</code></td><td>MySQL and MariaDB table options: <code>engine</code>, <code>charset</code>, <code>collation</code>, <code>comment</code>. Any other key is refused</td></tr></tbody></table><h2 id="identifiers" tabindex="-1">Identifiers <a class="header-anchor" href="#identifiers" aria-label="Permalink to &quot;Identifiers&quot;">​</a></h2><h3 id="id" tabindex="-1"><code>#[Id]</code> <a class="header-anchor" href="#id" aria-label="Permalink to &quot;`#[Id]`&quot;">​</a></h3><p>Marks the identifier property. Each entity has exactly one. No parameter.</p><h3 id="generatedvalue" tabindex="-1"><code>#[GeneratedValue]</code> <a class="header-anchor" href="#generatedvalue" aria-label="Permalink to &quot;`#[GeneratedValue]`&quot;">​</a></h3><p>Lets the identifier be generated. Property attribute, next to <code>#[Id]</code>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>strategy</code></td><td><code>GenerationStrategy::Auto</code></td><td><code>Auto</code>: <code>Identity</code> under MySQL, MariaDB and SQLite, <code>Sequence</code> under PostgreSQL. <code>Identity</code>: auto-increment column. <code>Sequence</code>: database sequence. <code>UuidV7</code>: generated by Prism before the <code>INSERT</code>, on a <code>uuid</code> column</td></tr><tr><td><code>sequenceName</code></td><td><code>null</code></td><td>The sequence of <code>Auto</code> or <code>Sequence</code>. <code>null</code>: <code>&lt;table&gt;_id_seq</code></td></tr></tbody></table><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h2><h3 id="column" tabindex="-1"><code>#[Column]</code> <a class="header-anchor" href="#column" aria-label="Permalink to &quot;`#[Column]`&quot;">​</a></h3><p>Stores a property in a column. Every <code>null</code> parameter is deduced from the PHP type. See <a href="/prism/guide/mapping#columns-and-types">Columns and types</a>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td><code>null</code></td><td>The column name. <code>null</code>: the property name in snake case</td></tr><tr><td><code>type</code></td><td><code>null</code></td><td><code>string</code>, <code>text</code>, <code>integer</code>, <code>bigint</code>, <code>smallint</code>, <code>boolean</code>, <code>decimal</code>, <code>float</code>, <code>datetime_immutable</code>, <code>date_immutable</code>, <code>time_immutable</code>, <code>json</code>, <code>uuid</code>, <code>binary</code>, or a custom type. <code>null</code>: deduced from the PHP type</td></tr><tr><td><code>length</code></td><td><code>null</code></td><td>Length of a <code>string</code> or <code>binary</code> column. <code>null</code>: 255 for a <code>string</code></td></tr><tr><td><code>nullable</code></td><td><code>null</code></td><td><code>null</code>: deduced from the PHP type (<code>?string</code>). A value that contradicts the type is a mapping error</td></tr><tr><td><code>unique</code></td><td><code>false</code></td><td>A unique constraint on this column alone; per tenant on a <code>#[Tenanted]</code> entity, on live rows on a <code>#[SoftDeletable]</code> one</td></tr><tr><td><code>precision</code></td><td><code>null</code></td><td>Total number of digits of a <code>decimal</code>, from 1 to 65; required for a <code>decimal</code></td></tr><tr><td><code>scale</code></td><td><code>null</code></td><td>Digits after the decimal point of a <code>decimal</code>, from 0 to 30, at most <code>precision</code>; required for a <code>decimal</code></td></tr><tr><td><code>enumType</code></td><td><code>null</code></td><td>The backed enum of the property. <code>null</code>: read from the PHP type</td></tr><tr><td><code>default</code></td><td><code>null</code></td><td>The default value of the column in the database</td></tr><tr><td><code>sensitive</code></td><td><code>false</code></td><td>The value is written as <code>***</code> in the audit log</td></tr><tr><td><code>insertable</code></td><td><code>true</code></td><td><code>false</code>: the column is left out of <code>INSERT</code> statements</td></tr><tr><td><code>updatable</code></td><td><code>true</code></td><td><code>false</code>: the column is left out of <code>UPDATE</code> statements, for a column computed by the database</td></tr><tr><td><code>fixed</code></td><td><code>false</code></td><td>Fixed length: <code>CHAR</code> or <code>BINARY</code> instead of <code>VARCHAR</code> or <code>VARBINARY</code>; needs a <code>length</code></td></tr><tr><td><code>dimensions</code></td><td><code>null</code></td><td>The dimension of a <code>vector</code> column, from 1 to 16,000; required for a <code>vector</code>. A vector of another size is refused before it is written. See <a href="/prism/guide/vector-search#a-vector-field">Vector search</a></td></tr><tr><td><code>lazy</code></td><td><code>null</code></td><td><code>true</code>: the field is not read with the entity, only on first access, for the whole batch. <code>null</code>: <code>true</code> for a <code>Prism\\Orm\\Vector\\Vector</code> property, <code>false</code> otherwise; only a <code>Vector</code> can be lazy</td></tr></tbody></table><h3 id="version" tabindex="-1"><code>#[Version]</code> <a class="header-anchor" href="#version" aria-label="Permalink to &quot;`#[Version]`&quot;">​</a></h3><p>Optimistic locking: the field is checked and incremented by each <code>UPDATE</code>, and a concurrent change throws <code>OptimisticLockException</code>. On an <code>int</code> or <code>\\DateTimeImmutable</code> property, next to <code>#[Column]</code>. No parameter.</p><h2 id="embeddables" tabindex="-1">Embeddables <a class="header-anchor" href="#embeddables" aria-label="Permalink to &quot;Embeddables&quot;">​</a></h2><h3 id="embeddable" tabindex="-1"><code>#[Embeddable]</code> <a class="header-anchor" href="#embeddable" aria-label="Permalink to &quot;`#[Embeddable]`&quot;">​</a></h3><p>Makes a class a value object stored in the columns of the entity that contains it. Class attribute; its properties carry <code>#[Column]</code>. No parameter.</p><h3 id="embedded" tabindex="-1"><code>#[Embedded]</code> <a class="header-anchor" href="#embedded" aria-label="Permalink to &quot;`#[Embedded]`&quot;">​</a></h3><p>Stores an embeddable in the entity. Property attribute. A nullable embeddable is <code>null</code> when all its columns are <code>NULL</code>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>class</code></td><td><code>null</code></td><td>The embeddable class. <code>null</code>: the property type</td></tr><tr><td><code>columnPrefix</code></td><td><code>null</code></td><td><code>null</code>: the property name in snake case and <code>_</code> (<code>billing_address_</code>). <code>false</code>: no prefix. A string: that prefix</td></tr></tbody></table><h2 id="indexes" tabindex="-1">Indexes <a class="header-anchor" href="#indexes" aria-label="Permalink to &quot;Indexes&quot;">​</a></h2><h3 id="index" tabindex="-1"><code>#[Index]</code> <a class="header-anchor" href="#index" aria-label="Permalink to &quot;`#[Index]`&quot;">​</a></h3><p>An index on one or more fields. Class attribute, repeatable. On a <code>#[Tenanted]</code> entity, <code>tenant_id</code> comes first.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>fields</code></td><td></td><td>The fields indexed, in order: PHP properties, owning <code>ManyToOne</code> or <code>OneToOne</code> relations (their foreign key column), or <code>address.city</code> for a field of an embeddable</td></tr><tr><td><code>name</code></td><td><code>null</code></td><td>The index name. <code>null</code>: generated from a hash of the columns, stable from one diff to the next</td></tr><tr><td><code>where</code></td><td><code>null</code></td><td>Accepted, but not applied yet: the index covers every row, which makes it wider, never wrong. Partial indexes with a free condition are planned after 1.0</td></tr></tbody></table><h3 id="uniqueconstraint" tabindex="-1"><code>#[UniqueConstraint]</code> <a class="header-anchor" href="#uniqueconstraint" aria-label="Permalink to &quot;`#[UniqueConstraint]`&quot;">​</a></h3><p>A unique constraint on one or more fields. Class attribute, repeatable. On a <code>#[Tenanted]</code> entity, unique per tenant; on a <code>#[SoftDeletable]</code> entity, unique among the rows that are not deleted.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>fields</code></td><td></td><td>The fields of the constraint: PHP properties or owning <code>ManyToOne</code> / <code>OneToOne</code> relations</td></tr><tr><td><code>name</code></td><td><code>null</code></td><td>The constraint name. <code>null</code>: generated, stable</td></tr><tr><td><code>where</code></td><td><code>null</code></td><td>Not supported yet: a unique constraint with a <code>where</code> is refused when the schema is built, since enforcing it without its condition would reject valid rows</td></tr></tbody></table><h2 id="vector-search" tabindex="-1">Vector search <a class="header-anchor" href="#vector-search" aria-label="Permalink to &quot;Vector search&quot;">​</a></h2><p>See <a href="/prism/guide/vector-search">Vector search</a>. Not on MySQL, which has no vector type: these attributes are refused when the mapping is validated for it.</p><h3 id="vectorindex" tabindex="-1"><code>#[VectorIndex]</code> <a class="header-anchor" href="#vectorindex" aria-label="Permalink to &quot;`#[VectorIndex]`&quot;">​</a></h3><p>An HNSW index on a <code>vector</code> field, used by <code>nearest()</code>, <code>hybridSearch()</code> and <code>distanceTo()</code>. Property attribute, next to <code>#[Column(dimensions: …)]</code>. On MariaDB, the column must be <code>NOT NULL</code>, and a table has one vector index at most.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>distance</code></td><td><code>Distance::Cosine</code></td><td><code>Distance::Cosine</code>, <code>Distance::Euclidean</code>, or <code>Distance::InnerProduct</code> (PostgreSQL and SQLite only). Also the distance of <code>nearest()</code> on this field</td></tr><tr><td><code>m</code></td><td><code>16</code></td><td>Connections per node of the graph, from 2 to 100</td></tr><tr><td><code>efConstruction</code></td><td><code>64</code></td><td>Search width while building the graph, from 4 to 1,000, at least <code>2 × m</code></td></tr></tbody></table><h3 id="fulltextindex" tabindex="-1"><code>#[FullTextIndex]</code> <a class="header-anchor" href="#fulltextindex" aria-label="Permalink to &quot;`#[FullTextIndex]`&quot;">​</a></h3><p>A full-text index on text fields, searched by <code>hybridSearch()</code>. Class attribute, repeatable. <code>FULLTEXT</code> on MySQL and MariaDB, a GIN index on <code>to_tsvector()</code> on PostgreSQL, scored in PHP on SQLite.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>fields</code></td><td></td><td>The <code>string</code> or <code>text</code> fields indexed</td></tr><tr><td><code>language</code></td><td><code>&#39;simple&#39;</code></td><td>The text search configuration of PostgreSQL: <code>english</code>, <code>french</code>, <code>simple</code> (no stemming)… Ignored by the other databases</td></tr><tr><td><code>name</code></td><td><code>null</code></td><td>The index name, and <code>HybridOptions::$fullTextIndex</code> when the entity has several. <code>null</code>: generated, stable</td></tr></tbody></table><h3 id="embeddedvector" tabindex="-1"><code>#[EmbeddedVector]</code> <a class="header-anchor" href="#embeddedvector" aria-label="Permalink to &quot;`#[EmbeddedVector]`&quot;">​</a></h3><p>Keeps a <code>vector</code> field computed from text fields. Property attribute, next to <code>#[Column(dimensions: …)]</code>. Adds two columns without properties, <code>&lt;column&gt;_stale</code> and <code>&lt;column&gt;_model</code>. A change of a source field makes the vector stale at flush; after the commit, the stale rows go to the embedding scheduler. A stale vector is left out of <code>nearest()</code>. See <a href="/prism/guide/vector-search#keeping-embeddings-up-to-date">Keeping embeddings up to date</a>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>source</code></td><td></td><td>The <code>string</code> or <code>text</code> field, or the list of fields, whose text is embedded, joined by a blank line</td></tr><tr><td><code>model</code></td><td><code>&#39;default&#39;</code></td><td>The name of the embedding provider, in the <code>EmbeddingProviderRegistry</code> (<code>prism.embeddings.providers</code> in Symfony); its dimension must be the one of the column</td></tr></tbody></table><h2 id="relations" tabindex="-1">Relations <a class="header-anchor" href="#relations" aria-label="Permalink to &quot;Relations&quot;">​</a></h2><p>See <a href="/prism/guide/relations">Relations</a>. In the tables below, <code>cascade</code> is a list of <code>Cascade::Persist</code>, <code>Cascade::Remove</code> and <code>Cascade::Detach</code>, and <code>fetch</code> is <code>Fetch::Lazy</code>, <code>Fetch::Eager</code> or <code>Fetch::ExtraLazy</code>.</p><h3 id="manytoone" tabindex="-1"><code>#[ManyToOne]</code> <a class="header-anchor" href="#manytoone" aria-label="Permalink to &quot;`#[ManyToOne]`&quot;">​</a></h3><p>The owning side of a many-to-one relation: it holds the foreign key.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>targetEntity</code></td><td><code>null</code></td><td>The target class. <code>null</code>: the property type</td></tr><tr><td><code>inversedBy</code></td><td><code>null</code></td><td>The property of the target that holds the other side</td></tr><tr><td><code>cascade</code></td><td><code>[]</code></td><td>Operations propagated to the target</td></tr><tr><td><code>fetch</code></td><td><code>Fetch::Lazy</code></td><td>When the target loads</td></tr><tr><td><code>joinColumn</code></td><td><code>null</code></td><td>The foreign key column. <code>null</code>: <code>&lt;property&gt;_id</code></td></tr><tr><td><code>onDelete</code></td><td><code>OnDelete::Restrict</code></td><td>What the database does when the target row is deleted: <code>Restrict</code>, <code>Cascade</code>, <code>SetNull</code>, <code>NoAction</code></td></tr><tr><td><code>batchSize</code></td><td><code>null</code></td><td>Batch size of batch fetching, from 1 to 1000. <code>null</code>: the entity manager&#39;s, 100 by default</td></tr><tr><td><code>batch</code></td><td><code>true</code></td><td><code>false</code>: no batch fetching for this relation</td></tr><tr><td><code>foreignKey</code></td><td><code>null</code></td><td>The foreign key constraint name. <code>null</code>: generated, stable</td></tr></tbody></table><h3 id="onetomany" tabindex="-1"><code>#[OneToMany]</code> <a class="header-anchor" href="#onetomany" aria-label="Permalink to &quot;`#[OneToMany]`&quot;">​</a></h3><p>The inverse side of a <code>ManyToOne</code>, as a <code>Collection</code>. It has no column.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>targetEntity</code></td><td></td><td>The class of the elements; required</td></tr><tr><td><code>mappedBy</code></td><td></td><td>The <code>ManyToOne</code> property of the target; required</td></tr><tr><td><code>cascade</code></td><td><code>[]</code></td><td>Operations propagated to the elements</td></tr><tr><td><code>fetch</code></td><td><code>Fetch::Lazy</code></td><td><code>ExtraLazy</code>: <code>count()</code> runs a <code>COUNT</code> query without loading the elements</td></tr><tr><td><code>orphanRemoval</code></td><td><code>false</code></td><td>An element removed from the collection is deleted at the flush</td></tr><tr><td><code>indexBy</code></td><td><code>null</code></td><td>A field of the target whose values key the collection</td></tr><tr><td><code>batchSize</code></td><td><code>null</code></td><td>Batch size of batch fetching, from 1 to 1000</td></tr><tr><td><code>batch</code></td><td><code>true</code></td><td><code>false</code>: no batch fetching for this collection</td></tr></tbody></table><h3 id="onetoone" tabindex="-1"><code>#[OneToOne]</code> <a class="header-anchor" href="#onetoone" aria-label="Permalink to &quot;`#[OneToOne]`&quot;">​</a></h3><p>A one-to-one relation. The owning side holds a unique foreign key; the inverse side has <code>mappedBy</code> and no column.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>targetEntity</code></td><td><code>null</code></td><td>The target class. <code>null</code>: the property type</td></tr><tr><td><code>mappedBy</code></td><td><code>null</code></td><td>On the inverse side: the property of the target that owns the relation</td></tr><tr><td><code>inversedBy</code></td><td><code>null</code></td><td>On the owning side: the property of the target that holds the other side</td></tr><tr><td><code>cascade</code></td><td><code>[]</code></td><td>Operations propagated to the target</td></tr><tr><td><code>fetch</code></td><td><code>Fetch::Lazy</code></td><td>When the target loads; the inverse side is always loaded with its owner, in a batch</td></tr><tr><td><code>joinColumn</code></td><td><code>null</code></td><td>Owning side only: the foreign key column. <code>null</code>: <code>&lt;property&gt;_id</code></td></tr><tr><td><code>onDelete</code></td><td><code>OnDelete::Restrict</code></td><td>Owning side only: what the database does when the target row is deleted</td></tr><tr><td><code>orphanRemoval</code></td><td><code>false</code></td><td>A target replaced or set to <code>null</code> is deleted at the flush</td></tr><tr><td><code>batchSize</code></td><td><code>null</code></td><td>Batch size of batch fetching, from 1 to 1000</td></tr><tr><td><code>batch</code></td><td><code>true</code></td><td><code>false</code>: no batch fetching for this relation</td></tr><tr><td><code>foreignKey</code></td><td><code>null</code></td><td>Owning side only: the foreign key constraint name</td></tr></tbody></table><h3 id="manytomany" tabindex="-1"><code>#[ManyToMany]</code> <a class="header-anchor" href="#manytomany" aria-label="Permalink to &quot;`#[ManyToMany]`&quot;">​</a></h3><p>A many-to-many relation through a join table. The owning side, with <code>inversedBy</code> or without another side, writes the join table.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>targetEntity</code></td><td></td><td>The class of the elements; required</td></tr><tr><td><code>mappedBy</code></td><td><code>null</code></td><td>On the inverse side: the property of the target that owns the relation</td></tr><tr><td><code>inversedBy</code></td><td><code>null</code></td><td>On the owning side: the property of the target that holds the other side</td></tr><tr><td><code>cascade</code></td><td><code>[]</code></td><td>Operations propagated to the elements</td></tr><tr><td><code>fetch</code></td><td><code>Fetch::Lazy</code></td><td><code>ExtraLazy</code>: <code>count()</code> without loading the elements</td></tr><tr><td><code>indexBy</code></td><td><code>null</code></td><td>A field of the target whose values key the collection</td></tr><tr><td><code>batchSize</code></td><td><code>null</code></td><td>Batch size of batch fetching, from 1 to 1000</td></tr><tr><td><code>batch</code></td><td><code>true</code></td><td><code>false</code>: no batch fetching for this collection</td></tr></tbody></table><h3 id="jointable" tabindex="-1"><code>#[JoinTable]</code> <a class="header-anchor" href="#jointable" aria-label="Permalink to &quot;`#[JoinTable]`&quot;">​</a></h3><p>The join table of a <code>ManyToMany</code>, on the owning side.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td><code>null</code></td><td>The table name. <code>null</code>: <code>&lt;owner table&gt;_&lt;target table&gt;</code></td></tr><tr><td><code>joinColumn</code></td><td><code>null</code></td><td>The column pointing to the owner. <code>null</code>: <code>&lt;owner table&gt;_id</code></td></tr><tr><td><code>inverseJoinColumn</code></td><td><code>null</code></td><td>The column pointing to the target. <code>null</code>: <code>&lt;target table&gt;_id</code></td></tr><tr><td><code>onDelete</code></td><td><code>OnDelete::Cascade</code></td><td>What the database does with the links when an owner or a target is deleted</td></tr></tbody></table><h3 id="orderby" tabindex="-1"><code>#[OrderBy]</code> <a class="header-anchor" href="#orderby" aria-label="Permalink to &quot;`#[OrderBy]`&quot;">​</a></h3><p>The order of a <code>OneToMany</code> or <code>ManyToMany</code> collection, applied in SQL and kept by batch fetching.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>fields</code></td><td></td><td>Field → <code>Order::Asc</code> or <code>Order::Desc</code>, of <code>Prism\\Dbal\\Query\\Order</code>, the enum <code>findBy()</code> and the query builder take too: <code>[&#39;position&#39; =&gt; Order::Asc]</code></td></tr></tbody></table><h2 id="lifecycle" tabindex="-1">Lifecycle <a class="header-anchor" href="#lifecycle" aria-label="Permalink to &quot;Lifecycle&quot;">​</a></h2><h3 id="haslifecyclecallbacks" tabindex="-1"><code>#[HasLifecycleCallbacks]</code> <a class="header-anchor" href="#haslifecyclecallbacks" aria-label="Permalink to &quot;`#[HasLifecycleCallbacks]`&quot;">​</a></h3><p>Enables the lifecycle callbacks declared on the methods of the entity. Class attribute. No parameter.</p><h3 id="prepersist" tabindex="-1"><code>#[PrePersist]</code> <a class="header-anchor" href="#prepersist" aria-label="Permalink to &quot;`#[PrePersist]`&quot;">​</a></h3><p>The method runs before the <code>INSERT</code> of the entity, in the transaction of the flush; a change it makes is inserted. No parameter.</p><h3 id="postpersist" tabindex="-1"><code>#[PostPersist]</code> <a class="header-anchor" href="#postpersist" aria-label="Permalink to &quot;`#[PostPersist]`&quot;">​</a></h3><p>The method runs after the commit of the flush that inserted the entity. No parameter.</p><h3 id="preupdate" tabindex="-1"><code>#[PreUpdate]</code> <a class="header-anchor" href="#preupdate" aria-label="Permalink to &quot;`#[PreUpdate]`&quot;">​</a></h3><p>The method runs before the <code>UPDATE</code> of the entity; a change it makes is included. No parameter.</p><h3 id="postupdate" tabindex="-1"><code>#[PostUpdate]</code> <a class="header-anchor" href="#postupdate" aria-label="Permalink to &quot;`#[PostUpdate]`&quot;">​</a></h3><p>The method runs after the commit of the flush that updated the entity. No parameter.</p><h3 id="preremove" tabindex="-1"><code>#[PreRemove]</code> <a class="header-anchor" href="#preremove" aria-label="Permalink to &quot;`#[PreRemove]`&quot;">​</a></h3><p>The method runs when <code>remove()</code> is called, before the entity is scheduled for deletion. No parameter.</p><h3 id="postremove" tabindex="-1"><code>#[PostRemove]</code> <a class="header-anchor" href="#postremove" aria-label="Permalink to &quot;`#[PostRemove]`&quot;">​</a></h3><p>The method runs after the commit of the flush that deleted the entity. No parameter.</p><h3 id="postload" tabindex="-1"><code>#[PostLoad]</code> <a class="header-anchor" href="#postload" aria-label="Permalink to &quot;`#[PostLoad]`&quot;">​</a></h3><p>The method runs after the entity is loaded from the database, never when the identity map returns an entity already loaded. Since the constructor is not called, this is where derived state is computed. No parameter.</p><h3 id="entitylisteners" tabindex="-1"><code>#[EntityListeners]</code> <a class="header-anchor" href="#entitylisteners" aria-label="Permalink to &quot;`#[EntityListeners]`&quot;">​</a></h3><p>Classes whose methods, carrying the lifecycle attributes above, receive the entity as first argument. Class attribute.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>listeners</code></td><td></td><td>The listener classes. In Symfony, a class with <code>#[AsEntityListener]</code> is a service</td></tr></tbody></table><h2 id="multi-tenancy-and-behaviors" tabindex="-1">Multi-tenancy and behaviors <a class="header-anchor" href="#multi-tenancy-and-behaviors" aria-label="Permalink to &quot;Multi-tenancy and behaviors&quot;">​</a></h2><h3 id="tenanted" tabindex="-1"><code>#[Tenanted]</code> <a class="header-anchor" href="#tenanted" aria-label="Permalink to &quot;`#[Tenanted]`&quot;">​</a></h3><p>Isolates the entity by tenant: a <code>tenant_id</code> column, filled and filtered by Prism. See <a href="/prism/guide/multi-tenancy">Multi-tenancy</a>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>global</code></td><td><code>false</code></td><td>Rows without a tenant are shared: every tenant reads them, only the system mode writes them</td></tr><tr><td><code>column</code></td><td><code>null</code></td><td>The name of the tenant column. <code>null</code>: <code>tenant_id</code></td></tr><tr><td><code>strictForeignKeys</code></td><td><code>false</code></td><td>Composite foreign keys <code>(tenant_id, id)</code>, so that the database itself refuses a cross-tenant relation. Not supported in 1.0, which has single-column keys: <code>true</code> is refused by the mapping validator. Prism refuses cross-tenant relations at flush instead</td></tr></tbody></table><h3 id="timestampable" tabindex="-1"><code>#[Timestampable]</code> <a class="header-anchor" href="#timestampable" aria-label="Permalink to &quot;`#[Timestampable]`&quot;">​</a></h3><p>Sets the creation and update dates, in UTC. See <a href="/prism/guide/audit#timestamps-and-authors">Audit and behaviors</a>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>createdAt</code></td><td><code>&#39;createdAt&#39;</code></td><td>The mapped field set at <code>INSERT</code>, unless already set</td></tr><tr><td><code>updatedAt</code></td><td><code>&#39;updatedAt&#39;</code></td><td>The mapped field set when another field changes. <code>null</code>: never set</td></tr></tbody></table><h3 id="blameable" tabindex="-1"><code>#[Blameable]</code> <a class="header-anchor" href="#blameable" aria-label="Permalink to &quot;`#[Blameable]`&quot;">​</a></h3><p>Sets the author of the creation and of the last update, from the <code>ActorProvider</code>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>createdBy</code></td><td><code>&#39;createdBy&#39;</code></td><td>The mapped field set at <code>INSERT</code>, unless already set</td></tr><tr><td><code>updatedBy</code></td><td><code>&#39;updatedBy&#39;</code></td><td>The mapped field set when another field changes. <code>null</code>: never set</td></tr></tbody></table><h3 id="softdeletable" tabindex="-1"><code>#[SoftDeletable]</code> <a class="header-anchor" href="#softdeletable" aria-label="Permalink to &quot;`#[SoftDeletable]`&quot;">​</a></h3><p>Turns <code>remove()</code> into an <code>UPDATE</code> of the deletion date; deleted rows are left out of reads. See <a href="/prism/guide/audit#soft-delete">Soft delete</a>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>field</code></td><td><code>&#39;deletedAt&#39;</code></td><td>The mapped, nullable <code>\\DateTimeImmutable</code> field that holds the deletion date</td></tr></tbody></table><h3 id="auditable" tabindex="-1"><code>#[Auditable]</code> <a class="header-anchor" href="#auditable" aria-label="Permalink to &quot;`#[Auditable]`&quot;">​</a></h3><p>Writes each change of the entity into <code>prism_audit_log</code>, in the transaction of the flush. See <a href="/prism/guide/audit#audit-log">Audit log</a>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>exclude</code></td><td><code>[]</code></td><td>Fields left out of the changeset, <code>updatedAt</code> for example</td></tr><tr><td><code>retention</code></td><td><code>null</code></td><td>How long the rows are kept, as an ISO 8601 duration (<code>&#39;P10Y&#39;</code>), for <code>db:audit:purge</code>. <code>null</code>: purged only with <code>--older-than</code></td></tr></tbody></table><h2 id="symfony-bundle" tabindex="-1">Symfony bundle <a class="header-anchor" href="#symfony-bundle" aria-label="Permalink to &quot;Symfony bundle&quot;">​</a></h2><h3 id="uniqueentity" tabindex="-1"><code>#[UniqueEntity]</code> <a class="header-anchor" href="#uniqueentity" aria-label="Permalink to &quot;`#[UniqueEntity]`&quot;">​</a></h3><p><code>Prism\\Bundle\\Validator\\UniqueEntity</code>: a validation constraint, true when no other entity of the class has the same values. Class attribute, repeatable.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>fields</code></td><td></td><td>A field or a <code>ToOne</code> relation, or a list of them checked together</td></tr><tr><td><code>message</code></td><td><code>&#39;This value is already used.&#39;</code></td><td>The violation message</td></tr><tr><td><code>errorPath</code></td><td><code>null</code></td><td>The property the violation is attached to. <code>null</code>: the first field</td></tr><tr><td><code>ignoreNull</code></td><td><code>true</code></td><td>A <code>null</code> value is never a duplicate, like in a database unique constraint</td></tr><tr><td><code>entityManager</code></td><td><code>null</code></td><td>The entity manager to query. <code>null</code>: the one that maps the class</td></tr><tr><td><code>groups</code></td><td><code>null</code></td><td>Validation groups</td></tr><tr><td><code>payload</code></td><td><code>null</code></td><td>Symfony&#39;s constraint payload</td></tr></tbody></table><h3 id="asprismlistener" tabindex="-1"><code>#[AsPrismListener]</code> <a class="header-anchor" href="#asprismlistener" aria-label="Permalink to &quot;`#[AsPrismListener]`&quot;">​</a></h3><p><code>Prism\\Bundle\\Attribute\\AsPrismListener</code>: listens to a Prism event (<code>PrePersistEvent</code>, <code>PostFlushEvent</code>...). On a class (its <code>__invoke()</code> method) or a method; repeatable.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>event</code></td><td><code>null</code></td><td>The event class. <code>null</code>: the type of the method&#39;s first parameter</td></tr><tr><td><code>method</code></td><td><code>null</code></td><td>On a class: the method to call. <code>null</code>: <code>__invoke</code></td></tr><tr><td><code>entityManager</code></td><td><code>null</code></td><td>The entity manager whose events are listened to. <code>null</code>: all of them</td></tr><tr><td><code>priority</code></td><td><code>0</code></td><td>Higher priorities run first</td></tr></tbody></table><h3 id="asentitylistener" tabindex="-1"><code>#[AsEntityListener]</code> <a class="header-anchor" href="#asentitylistener" aria-label="Permalink to &quot;`#[AsEntityListener]`&quot;">​</a></h3><p><code>Prism\\Bundle\\Attribute\\AsEntityListener</code>: makes an entity listener, named in <code>#[EntityListeners]</code>, a service with its dependencies. Without it, the listener is created without arguments. No parameter.</p><h3 id="asembeddingprovider" tabindex="-1"><code>#[AsEmbeddingProvider]</code> <a class="header-anchor" href="#asembeddingprovider" aria-label="Permalink to &quot;`#[AsEmbeddingProvider]`&quot;">​</a></h3><p><code>Prism\\Bundle\\Attribute\\AsEmbeddingProvider</code>: registers an <code>EmbeddingProvider</code> service under a name, the one <code>#[EmbeddedVector(model:)]</code> gives. Without it, an autoconfigured provider is registered under its service id. See <a href="/prism/bundle/symfony#embeddings">Embeddings</a>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td><code>&#39;default&#39;</code></td><td>The name of the provider</td></tr></tbody></table><h3 id="mapentity" tabindex="-1"><code>#[MapEntity]</code> <a class="header-anchor" href="#mapentity" aria-label="Permalink to &quot;`#[MapEntity]`&quot;">​</a></h3><p><code>Prism\\Bundle\\Attribute\\MapEntity</code>: how a controller argument typed with an entity is loaded from the route. Without it, the identifier is the route parameter named after the argument, or <code>{id}</code>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>null</code></td><td>The route parameter that holds the identifier</td></tr><tr><td><code>mapping</code></td><td><code>null</code></td><td>Route parameter → field, looked up with <code>findOneBy()</code>: <code>[&#39;number&#39; =&gt; &#39;number&#39;]</code></td></tr><tr><td><code>entityManager</code></td><td><code>null</code></td><td>The entity manager. <code>null</code>: the first one that maps the class</td></tr><tr><td><code>disabled</code></td><td><code>false</code></td><td>Leaves the argument to the other value resolvers</td></tr></tbody></table><h2 id="migrations" tabindex="-1">Migrations <a class="header-anchor" href="#migrations" aria-label="Permalink to &quot;Migrations&quot;">​</a></h2><h3 id="ignorelint" tabindex="-1"><code>#[IgnoreLint]</code> <a class="header-anchor" href="#ignorelint" aria-label="Permalink to &quot;`#[IgnoreLint]`&quot;">​</a></h3><p><code>Prism\\Migrations\\Lint\\IgnoreLint</code>: silences one linter rule for a migration. Class attribute, repeatable.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>code</code></td><td></td><td>The rule, <code>&#39;L12&#39;</code> for example</td></tr><tr><td><code>reason</code></td><td></td><td>Why the case is accepted; required, and shown by <code>db:migrations:lint</code></td></tr></tbody></table><h2 id="test-pack" tabindex="-1">Test pack <a class="header-anchor" href="#test-pack" aria-label="Permalink to &quot;Test pack&quot;">​</a></h2><h3 id="withrealtransactions" tabindex="-1"><code>#[WithRealTransactions]</code> <a class="header-anchor" href="#withrealtransactions" aria-label="Permalink to &quot;`#[WithRealTransactions]`&quot;">​</a></h3><p><code>Prism\\TestPack\\Attribute\\WithRealTransactions</code>: on a test class or method that uses <code>ResetDatabase</code>, disables the surrounding transaction: commits are real, and the schema is created again after the test. For a test that reads from another connection, or runs DDL under MySQL and MariaDB. No parameter.</p>',124)])])}const m=t(r,[["render",c]]);export{b as __pageData,m as default};
